def shade(cell, hexcolor):
    tcPr = cell._tc.get_or_add_tcPr(); shd = OxmlElement("w:shd")
    shd.set(qn("w:val"), "clear"); shd.set(qn("w:color"), "auto"); shd.set(qn("w:fill"), hexcolor); tcPr.append(shd)


doc = Document()
st = doc.styles["Normal"]; st.font.name = "Arial"; st.font.size = Pt(9)
st.element.rPr.rFonts.set(qn("w:eastAsia"), "Arial")
sec = doc.sections[0]; sec.orientation = WD_ORIENT.LANDSCAPE
sec.page_width, sec.page_height = sec.page_height, sec.page_width
for m in ("left_margin", "right_margin", "top_margin", "bottom_margin"):
    setattr(sec, m, Cm(1.8))

h = doc.add_paragraph(); r = h.add_run("Additional file 3. STROBE-MR checklist"); r.bold = True; r.font.size = Pt(13)
p = doc.add_paragraph(
    "Checklist of recommendations for reporting Mendelian randomization studies (STROBE-MR), completed for the manuscript "
    "\"Opposing locus-specific effects explain discordant Mendelian randomization estimates between age-related macular degeneration and stroke\". Recommendations are paraphrased from "
    "Skrivankova VW, et al. Strengthening the Reporting of Observational Studies in Epidemiology Using Mendelian Randomization: "
    "the STROBE-MR Statement. JAMA. 2021;326(16):1614-1621 (doi:10.1001/jama.2021.18236). Locations give the exact section and subsection headings of the "
    "manuscript (Methods – <subsection>, Results – <subsection>) and the Additional files; page and line numbers will be added after the final layout.")
p.paragraph_format.space_after = Pt(6)

t = doc.add_table(rows=1, cols=5); t.style = "Table Grid"
widths = [Cm(3.0), Cm(1.4), Cm(9.0), Cm(5.2), Cm(7.3)]
for i, txt in enumerate(["Section", "Item", "Recommendation", "Location in manuscript", "How addressed in this study"]):
    c = t.rows[0].cells[i]; c.text = ""; run = c.paragraphs[0].add_run(txt); run.bold = True; shade(c, "D9D9D9"); c.width = widths[i]
for sec_, item, rec, loc, how in ROWS:
    cells = t.add_row().cells
    for i, txt in enumerate([sec_, item, rec, loc, how]):
        cells[i].text = ""; run = cells[i].paragraphs[0].add_run(txt)
        if i == 0: run.bold = True
        cells[i].width = widths[i]
hdr = t.rows[0]._tr; trPr = hdr.get_or_add_trPr(); th = OxmlElement("w:tblHeader"); th.set(qn("w:val"), "true"); trPr.append(th)

doc.add_paragraph()
n = doc.add_paragraph("Items marked [To be completed by the authors] require author information (funding, code repository, competing interests).")
n.runs[0].italic = True
OUT.parent.mkdir(parents=True, exist_ok=True)
doc.save(OUT); print("saved", OUT, "items:", len(ROWS))
